const bankTexts = {"en": {"label": "MIDI OUT Bank - B-side Controls Test", "short": "B-side gray knobs assignable to CCs. RAM assignments.", "desc": "Hold a TRIG and turn an assigned gray knob to lock its CC value on that step. A LOCK badge appears. Step playback sends the saved CC number/value; the known base value returns when that note ends, including after Stop. FUNC + TRIG creates a parameter-only step without a MIDI note; its CC value holds until another CC change. SETTINGS returns to the same B-side lane. DATA cycles Note/Vel/Len with stock field highlighting. In B-side, SETTINGS + TRACK scrambles the values of assigned CC knobs on the selected lane; A-side SCRAMBLE is unchanged. SETTINGS assignment uses a silent draft while existing locks keep playing. Step/lane copy, paste and clear include these locks. CC assignments and CC locks are RAM-only and reset on project load/restart; Save Project does not save CC locks in this first test. MIDI notes, timing, older step locks and MIDI LFO saving are unchanged. Experimental gray-knob CC controls in MIDI B-side. Hold SETTINGS and turn a gray knob to select OFF or CC0-127. Common CC names appear in the stock-style window and long names scroll. Release SETTINGS, then turn the knob to send a value on the selected MIDI lane channel and port. Assignment itself sends nothing. Muted/disabled lanes send nothing; unassigned knobs retain their earlier behavior. A-side controls are unchanged. The first test keeps assignments in RAM only, so they reset after restart. Hardware-tested MIDI sequence saving and live recording remain included."}, "fr": {"label": "Banque MIDI OUT - Test contrôles B", "short": "Potards gris B assignables aux CC. Assignations RAM.", "desc": "TRIG maintenu + potard assigné verrouille son CC sur ce pas, badge LOCK. Lecture transmet numéro/valeur verrouillés ; la base connue revient à la fin de la note, même après Stop. FUNC + TRIG crée un pas de paramètres sans note MIDI ; sa valeur CC reste jusqu’au prochain changement CC. SETTINGS revient à la même voie B. DATA sélectionne Note/Vel/Len avec surbrillance stock. Côté B, SETTINGS + TRACK randomise les valeurs des potards CC assignés de la voie sélectionnée ; SCRAMBLE A reste inchangé. L’assignation SETTINGS utilise un brouillon silencieux sans suspendre les locks joués. Copie/colle/clear des pas/voies incluent les CC. Assignations et locks CC en RAM seulement, remis à zéro au chargement/redémarrage ; Save Project ne les conserve pas encore. Notes, timing, locks précédents et sauvegarde LFO MIDI inchangés. Test CC des potards gris côté MIDI B. SETTINGS + potard choisit OFF ou CC0-127. Noms courants dans une fenêtre style stock, défilement des noms longs. Relâchez SETTINGS puis tournez pour transmettre sur canal et port de la voie MIDI sélectionnée. Assignation silencieuse, voie muette/désactivée silencieuse, potards OFF inchangés. Côté A inchangé. Ce premier test garde les assignations en RAM seulement, remises à zéro au redémarrage. Sauvegarde des séquences MIDI et live-rec testés sur matériel conservés."}};
const bankFeature = {
 "id": "midi-bank-bundle",
 "cat": "seq",
 "status": "experimental",
 "label": "MIDI OUT Bank",
 "desc": "Test de sauvegarde MIDI et restauration au démarrage. Save Project écrit et vérifie les séquences B. Démarrage ou chargement d’un autre projet sauvegardé restaure ses séquences en arrière-plan. Attendre avant édition ou sauvegarde. Si le slot ne peut pas être associé, B reste accessible en RAM seule et les sauvegardes disque sont bloquées. Pas d’autosave des éditions. Écriture vérifiée sur matériel ; restauration après extinction à tester. Fichiers séparés hors backups Elektron. Sélections existantes, Model-TG et potard SPEED LFO2 conservés. Live-rec B inclus : RECORD + PLAY, puis PLAY avec RECORD maintenu pour changer la quantification. Save conserve notes, vélocité, durées en pas et retards au 1/64 de pas. Lit MBK2/MBK3, écrit MBK4 ; les anciennes versions ne lisent pas MBK4. Intégration live-rec/sauvegarde à tester sur matériel.",
 "requires": "model-tg",
 "credit": {
  "kind": "based",
  "who": "TinyGregAudio",
  "repo": "TinyGregAudio/Model-TG"
 },
 "license": "LICENSE-Model-TG",
 "variants": [
  {
   "id": "midi-bank-bundle",
   "label": null
  }
 ],
 "excludes": []
};
for (const key of ["label", "short", "desc"]) Object.defineProperty(bankFeature, key, {
  get: () => (bankTexts[document.documentElement.lang] || bankTexts.en)[key], configurable: true
});
window.MC_TWEAKS.features.push(bankFeature);
